object Main {
  def main(args: Array[String]): Unit = {
    val line = scala.io.StdIn.readLine()
    val parts = line.split(" ")
    val a = parts(0).toDouble
    val b = parts(1).toDouble
    println(a + b)
    println(a - b)
    println(a * b)
    println(a / b)
  }
}

